#include <memory>

void bad_usage() {
    int* raw_array = new int[10];

    // DANGER: Leads to Undefined Behavior
    // auto_ptr calls 'delete' instead of 'delete[]'
    // std::auto_ptr<int> array_ptr(raw_array);

    // A required C++03 solution for arrays:
    class ArrayDeleter {
        int* p;
    public:
        ArrayDeleter(int* ptr) : p(ptr) {}
        ~ArrayDeleter() { delete[] p; }
    };
    // ArrayDeleter safe_array_manager(raw_array);
}
